                dict(label='Consecuencias', points=[dict(text='Los encomenderos del Perú se rebelaron con Gonzalo Pizarro, el virrey Núñez Vela murió en la batalla de Iñaquito en 1546 y el presidente Pedro de la Gasca acabó derogando las leyes.', quotes=[Q('es_leyesnuevas','El virrey Núñez Vela logró escapar y organizó un ejército'), Q('en_leyesnuevas','He was opposed by a revolt of encomenderos and was killed in 1546')])]),
